/**
 * Dokan Stripe Connect — admin settings UX.
 *
 * Toggles the Live / Test credential sections on the WooCommerce settings
 * page based on the "Enable Test Mode" checkbox so admins only see the
 * credential set that applies to them.
 *
 * @since 5.0.7
 */
declare const jQuery: any;

( function ( $: any ) {
    $( function () {
        const prefix = '#woocommerce_dokan-stripe-connect_';
        const $toggle = $( prefix + 'testmode' );

        if ( ! $toggle.length ) {
            return;
        }

        const liveKeys = [ 'publishable_key', 'secret_key', 'client_id' ];
        const testKeys = [
            'test_publishable_key',
            'test_secret_key',
            'test_client_id',
        ];

        const rowsFor = ( keys: string[] ) =>
            $( keys.map( ( k ) => prefix + k ).join( ',' ) ).closest( 'tr' );

        const $liveTitle = $( prefix + 'live-credentials-title' );
        const $testTitle = $( prefix + 'test-credentials-title' );
        const $liveDesc = $liveTitle.next( 'p' );
        const $testDesc = $testTitle.next( 'p' );
        const $liveRows = rowsFor( liveKeys );
        const $testRows = rowsFor( testKeys );

        const sync = () => {
            const isTest = $toggle.is( ':checked' );

            $liveTitle.toggle( ! isTest );
            $liveDesc.toggle( ! isTest );
            $liveRows.toggle( ! isTest );

            $testTitle.toggle( isTest );
            $testDesc.toggle( isTest );
            $testRows.toggle( isTest );
        };

        sync();
        $toggle.on( 'change', sync );
    } );
} )( jQuery );
